<x-layouts.access-control :title="'Guest Access Cards'"><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><a href="{{ route('access-control.index') }}" class="text-sm font-semibold text-teal-700">← Security Center</a><h1 class="mt-2 text-2xl font-bold">Guest Access Cards</h1><p class="mt-1 text-sm text-slate-500">Issue and manage guest room credentials.</p></div><a href="{{ route('access-control.guest-cards.create') }}" class="rounded-xl bg-teal-600 px-4 py-2.5 text-sm font-bold text-white shadow-sm hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-teal-500">+ Issue guest card</a></div><form class="mt-6 flex flex-col gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:flex-row"><input name="search" value="{{ request('search') }}" class="rounded-lg border-slate-200 text-sm focus:border-teal-500 focus:ring-teal-500" placeholder="Search card or guest"><select name="status" class="rounded-lg border-slate-200 text-sm focus:border-teal-500 focus:ring-teal-500"><option value="">All statuses</option>@foreach(['active','suspended','revoked','blocked','expired'] as $status)<option value="{{ $status }}" @selected(request('status') === $status)>{{ ucfirst($status) }}</option>@endforeach</select><button class="rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white hover:bg-slate-700">Filter</button></form><div class="mt-5 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">Card</th><th class="px-5 py-3">Guest</th><th class="px-5 py-3">Room</th><th class="px-5 py-3">Issued</th><th class="px-5 py-3">Expiry</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-slate-100">@forelse($cards as $card)<tr class="hover:bg-slate-50"><td class="px-5 py-4 font-semibold">{{ $card->card_number }}</td><td class="px-5 py-4">{{ $card->guest?->full_name ?? 'Unassigned' }}</td><td class="px-5 py-4">{{ $card->notes ?: 'Assigned stay' }}</td><td class="px-5 py-4 text-slate-500">{{ optional($card->issued_at)->format('d M Y') }}</td><td class="px-5 py-4 text-slate-500">{{ optional($card->expires_at)->format('d M Y H:i') ?: 'No expiry' }}</td><td class="px-5 py-4"><x-access-status-badge :status="$card->status" /></td><td class="px-5 py-4 text-right"><div class="flex justify-end gap-2">@if($card->status !== 'active')<form method="POST" action="{{ route('access-control.cards.activate', $card) }}">@csrf<button class="text-xs font-semibold text-emerald-700">Activate</button></form>@else<form method="POST" action="{{ route('access-control.cards.suspend', $card) }}">@csrf<button class="text-xs font-semibold text-amber-700">Suspend</button></form>@endif<form method="POST" action="{{ route('access-control.cards.revoke', $card) }}">@csrf<button class="text-xs font-semibold text-red-700">Revoke</button></form></div></td></tr>@empty<tr><td colspan="7" class="px-5 py-12 text-center text-slate-500">No guest access cards have been issued.</td></tr>@endforelse</tbody></table></div><div class="border-t border-slate-100 px-5 py-4">{{ $cards->links() }}</div></div></x-layouts.access-control>
